const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const http = require('http');
const url = require('url');

// Cryptographic key cache service behind nginx reverse proxy
// Caches derived keys to disk for session resumption

const KEY_CACHE_DIR = process.env.KEY_CACHE_DIR || '/tmp/keycache';
const HMAC_SECRET = crypto.randomBytes(32);

class KeyDerivationCache {
  constructor(cacheDir) {
    this.cacheDir = cacheDir;
    this.pendingWrites = new Map();
    this._ensureCacheDir();
  }

  _ensureCacheDir() {
    if (!fs.existsSync(this.cacheDir)) {
      fs.mkdirSync(this.cacheDir, { mode: 0o700, recursive: true });
    }
  }

  _computeCacheId(sessionId, clientIp) {
    // Use HMAC to derive a safe filename from session parameters
    const hmac = crypto.createHmac('sha256', HMAC_SECRET);
    hmac.update(sessionId);
    hmac.update(clientIp);
    return hmac.digest('hex');
  }

  _getCachePath(cacheId) {
    // Construct path within cache directory
    const subdir = cacheId.substring(0, 2);
    const dirPath = path.join(this.cacheDir, subdir);
    if (!fs.existsSync(dirPath)) {
      fs.mkdirSync(dirPath, { mode: 0o700, recursive: true });
    }
    return path.join(dirPath, cacheId);
  }

  async deriveAndCache(sessionId, clientIp, salt) {
    const cacheId = this._computeCacheId(sessionId, clientIp);
    const cachePath = this._getCachePath(cacheId);

    // Check if we already have a cached key
    if (this._isCacheValid(cachePath)) {
      return this._readCachedKey(cachePath);
    }

    // Derive new key using PBKDF2
    const derivedKey = await this._deriveKey(sessionId, salt);

    // Write to cache for future session resumption
    await this._writeCacheEntry(cachePath, derivedKey, cacheId);

    return derivedKey;
  }

  _isCacheValid(cachePath) {
    try {
      const stats = fs.statSync(cachePath);
      const ageMs = Date.now() - stats.mtimeMs;
      // Cache entries valid for 1 hour
      return ageMs < 3600000 && stats.size === 80;
    } catch (e) {
      return false;
    }
  }

  _readCachedKey(cachePath) {
    // Read the cached derived key
    const data = fs.readFileSync(cachePath);
    const storedHmac = data.slice(0, 32);
    const keyMaterial = data.slice(32);

    // Verify integrity
    const expectedHmac = crypto.createHmac('sha256', HMAC_SECRET)
      .update(keyMaterial)
      .digest();

    if (!crypto.timingSafeEqual(storedHmac, expectedHmac)) {
      throw new Error('Cache integrity check failed');
    }

    return keyMaterial;
  }

  async _deriveKey(sessionId, salt) {
    return new Promise((resolve, reject) => {
      const saltBuf = Buffer.from(salt, 'hex');
      crypto.pbkdf2(sessionId, saltBuf, 100000, 48, 'sha512', (err, key) => {
        if (err) reject(err);
        else resolve(key);
      });
    });
  }

  async _writeCacheEntry(cachePath, keyMaterial, cacheId) {
    const hmac = crypto.createHmac('sha256', HMAC_SECRET)
      .update(keyMaterial)
      .digest();

    const payload = Buffer.concat([hmac, keyMaterial]);

    // Write atomically using temp file + rename
    const tempPath = cachePath + '.tmp.' + process.pid;

    // Record pending write to prevent races
    this.pendingWrites.set(cacheId, Date.now());

    try {
      // Check the target doesn't already exist as a symlink
      // before writing (TOCTOU: check then write)
      const targetExists = fs.existsSync(cachePath);
      if (targetExists) {
        const targetStats = fs.lstatSync(cachePath);
        if (targetStats.isSymbolicLink()) {
          fs.unlinkSync(cachePath);
        }
      }

      // Write to temp file first
      fs.writeFileSync(tempPath, payload, { mode: 0o600 });

      // Rename temp to final path
      // VULNERABILITY: Between the symlink check above and this rename,
      // an attacker can create a symlink at cachePath pointing to a
      // sensitive file. The rename overwrites the symlink's target.
      fs.renameSync(tempPath, cachePath);
    } finally {
      this.pendingWrites.delete(cacheId);
    }
  }
}

// HTTP server handling key derivation requests from reverse proxy
const cache = new KeyDerivationCache(KEY_CACHE_DIR);

const server = http.createServer(async (req, res) => {
  try {
    const parsed = url.parse(req.url, true);

    if (parsed.pathname !== '/derive-key' || req.method !== 'POST') {
      res.writeHead(404);
      res.end('Not found');
      return;
    }

    // Get client IP from reverse proxy header
    const clientIp = req.headers['x-forwarded-for'] || 
                     req.connection.remoteAddress;

    let body = '';
    req.on('data', chunk => { body += chunk; });
    await new Promise(resolve => req.on('end', resolve));

    const { sessionId, salt } = JSON.parse(body);

    if (!sessionId || !salt || typeof sessionId !== 'string' || 
        typeof salt !== 'string' || !/^[a-f0-9]{32,64}$/.test(salt)) {
      res.writeHead(400);
      res.end('Invalid parameters');
      return;
    }

    const derivedKey = await cache.deriveAndCache(sessionId, clientIp, salt);

    res.writeHead(200, { 'Content-Type': 'application/octet-stream' });
    res.end(derivedKey);
  } catch (err) {
    res.writeHead(500);
    res.end('Internal error');
  }
});

server.listen(8901, '127.0.0.1', () => {
  console.log('Key derivation cache service on :8901');
});

module.exports = { KeyDerivationCache };
